<!doctype html><html lang="id" translate="no" class="notranslate"><head><meta charset="utf-8"><meta name="google" content="notranslate"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifikasi Operator · <?=e(app_name())?></title><link rel="stylesheet" href="/assets/app.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/app.css'))?>"><link rel="stylesheet" href="/assets/operator-layout.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/operator-layout.css'))?>"><link rel="stylesheet" href="/assets/operator-notifications.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/operator-notifications.css'))?>"><style><?=theme_css_vars()?></style></head><body class="notification-page"><header><a href="/operator" aria-label="Kembali">←</a><div><small>PENGATURAN OPERATOR</small><h1>Notifikasi antrean</h1></div><span><?=e($user['name'])?></span></header><main><section class="notification-intro"><p>ATUR PERANGKAT INI</p><h2>Suara antrean baru</h2><span>Pengaturan tersimpan khusus untuk akun operator Anda dan berlaku pada layanan yang ditugaskan.</span></section><form id="notification-settings" class="notification-card" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label class="notification-toggle"><span><b>Aktifkan notifikasi</b><small>Bunyikan suara ketika tiket baru masuk.</small></span><input type="checkbox" name="enabled" <?=$notificationSettings['enabled']?'checked':''?>></label><div class="notification-grid"><label>Jenis suara<select name="sound_type"><option value="chime" <?=$notificationSettings['sound_type']==='chime'?'selected':''?>>Chime</option><option value="bell" <?=$notificationSettings['sound_type']==='bell'?'selected':''?>>Bell</option><option value="beep" <?=$notificationSettings['sound_type']==='beep'?'selected':''?>>Beep</option><option value="custom" <?=$notificationSettings['sound_type']==='custom'?'selected':''?>>Suara custom</option></select></label><label>Volume <output id="volume-output"><?=e((int)round((float)$notificationSettings['volume']*100))?>%</output><input type="range" name="volume" min="0" max="1" step="0.05" value="<?=e($notificationSettings['volume'])?>"></label></div><label class="notification-file">Upload suara custom <small>MP3, WAV, atau OGG · maksimal 10 MB</small><input type="file" name="sound_file" accept="audio/mpeg,audio/wav,audio/ogg"></label><?php if($notificationSettings['sound_url']):?><p class="current-sound">File aktif: <?=e(basename($notificationSettings['sound_url']))?></p><?php endif?><div class="notification-actions"><button type="button" class="secondary" id="test-notification">Tes suara</button><button type="submit">Simpan pengaturan</button></div><p id="notification-status" role="status">Siap disimpan.</p></form></main><script>window.QUEUE={csrf:<?=json_encode(csrf_token())?>,notification:<?=json_encode(['enabled'=>(bool)$notificationSettings['enabled'],'sound_type'=>$notificationSettings['sound_type'],'sound_url'=>$notificationSettings['sound_url'],'volume'=>(float)$notificationSettings['volume']],JSON_UNESCAPED_SLASHES)?>};</script><script src="/assets/operator-notifications.js?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/operator-notifications.js'))?>"></script></body></html>
